public static long findNthGoodInteger(long N) {
    long count = 0;
    long candidate = 0;

    while (count < N) {
        if (isGoodInteger(candidate)) {
            count++;
        }
        if (count < N) {
            candidate++;
        }
    }

    return candidate;
}

private static boolean isGoodInteger(long number) {
    while (number > 0) {
        long digit = number % 10;
        if (digit % 2 != 0) {
            return false;
        }
        number /= 10;
    }
    return true;
}
